sys_ui_action.script:
function confirmCancelCease() {
    var relatedList = GlideList2.get('x_canl_emails_eocn_retentions_case.REL:633d9741834e4a10de872b80ceaad3ec');
    if (!relatedList) {
        alert('Unable to find the Sold Products related list.');
        return false;
    }
    var selectedSysIds = relatedList.getChecked();
    if (!selectedSysIds) {
        alert('Please select one or more Sold Products from the related list.');
        return false;
    }
    var count = selectedSysIds.split(',').length;
    if (!confirm('Are you sure you want to cancel the cease request for ' + count + ' Sold Product(s)?')) {
        return false;
    }

    var gaValidate = new GlideAjax('CancelCeaseAjax');
    gaValidate.addParam('sysparm_name', 'validateCancelCease');
    gaValidate.addParam('sysparm_case_sys_id', g_form.getUniqueValue());
    gaValidate.addParam('sysparm_selected_ids', selectedSysIds);
    gaValidate.getXMLAnswer(function(answer) {
        var result = JSON.parse(answer);
        /*if (!result.valid) {
            var dialog = new GlideModal('glide_modal');
            dialog.setTitle('Cease Date Validation');
            dialog.setPreference('body', result.message);
            dialog.render();
            return;
        }*/
        if (!result.valid) {
            alert(result.message);
            return;
        }
        _executeCancelCease(selectedSysIds);
    });

    return false;
}

function _executeCancelCease(selectedSysIds) {
    var ga = new GlideAjax('CancelCeaseAjax');
    ga.addParam('sysparm_name', 'cancelSelected');
    ga.addParam('sysparm_case_id', g_form.getUniqueValue());
    ga.addParam('sysparm_selected_ids', selectedSysIds);
    ga.getXMLAnswer(function(answer) {
        var result = JSON.parse(answer);
        g_form.clearMessages();
        if (result.success) {
            g_form.addInfoMessage(result.message);
            if (result.cancelled && result.cancelled.length > 0) {
                g_form.addInfoMessage('Cancelled Products: ' + result.cancelled.join(', '));
            }
            if (result.newState && result.newStateLabel) {
                g_form.addOption('state', result.newState, result.newStateLabel);
                g_form.setValue('state', result.newState);
                g_form.setReadOnly('state', true);
            }
            var rl = GlideList2.get('x_canl_emails_eocn_retentions_case.REL:633d9741834e4a10de872b80ceaad3ec');
            if (rl) rl.refresh();
        } else {
            g_form.addErrorMessage(result.message);
        }
    });
}
